// Generated by tools/make-heroes.py from 0x72's "16x16 DungeonTileset II" v1.7
// (CC0, https://0x72.itch.io/dungeontileset-ii), some recoloured per class.
// Each frame is SVG path markup on a 16x28 grid, one path per colour. Do not edit by hand.

export type Sprite = { idle: readonly string[]; run: readonly string[] }

export const SPRITES = {
