// The item centred in a square viewBox, so every icon scales the same way.
export function itemSvg(name: ItemName, size = 16): string {
  const { width, height, paths } = ITEMS[name]
  const s = Math.max(width, height)
  const dx = (s - width) / 2
  const dy = (s - height) / 2
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${-dx} ${-dy} ${s} ${s}" width="${size}" height="${size}" shape-rendering="crispEdges">${paths}</svg>`
}

